from itertools import combinations

def interleave(a, b):
    out = []
    for ia in combinations(range(len(a) + len(b)), len(a)):
        ib = [i for i in range(len(a) + len(b)) if i not in ia]
        seq = [None] * (len(a) + len(b))
        for pos, i in zip(ia, a):
            seq[pos] = ("W", i)
        for pos, i in zip(ib, b):
            seq[pos] = ("R", i)
        out.append(seq)
    return out


def simulate(seq):
    db = "OLD"
    cache = {"k": "OLD"}
    buf = None
    for who, step in seq:
        if who == "W":
            if step == "DEL":
                cache.pop("k", None)
            elif step == "UPDATE":
                db = "NEW"
            elif step == "SLEEP":
                pass
        else:
            if step == "GET_MISS":
                buf = cache.get("k")
            elif step == "READ_DB":
                buf = db
            elif step == "SET_CACHE":
                # 双检兜底：回填前再确认缓存确实为空，避免覆盖他人已写入的新值
                if "k" not in cache:
                    cache["k"] = buf
    return cache.get("k"), db


READER = ["GET_MISS", "READ_DB", "SET_CACHE"]

plans = [
    ("A 先删缓存后更新库", ["DEL", "UPDATE"]),
    ("B 先更新库后删缓存", ["UPDATE", "DEL"]),
    ("C 更新库+删+延迟双删", ["UPDATE", "DEL", "SLEEP", "DEL"]),
]

print("方案对比（枚举写/读线程全部合法交错后统计）")
for name, writer in plans:
    seqs = interleave(writer, READER)
    dirty = sum(1 for s in seqs if simulate(s)[0] != simulate(s)[1])
    print("  %s: %2d 种交错 -> 脏 %2d 种 (%5.1f%%)" % (name, len(seqs), dirty, 100.0 * dirty / len(seqs)))

print("")
